#include "native_study.hpp"
#include "wordcard_ui.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace wordcard;
namespace fs=std::filesystem;
static WebPage decode(const J&p){WebPage o;o.title=str(p,"title");o.route=str(p,"route");o.key=str(p,"key");o.typed=str(p,"typed");o.prompt=str(p,"prompt");o.gap_mask=str(p,"gapMask");o.toast=str(p,"toast");o.keyboard=flag(p,"keyboard");o.shift=flag(p,"shift");o.symbols=flag(p,"symbols");o.can_submit=flag(p,"canSubmit");o.corrupt=flag(p,"corrupt");auto action=[&](const J&a){if(a.is_null())return -1;o.actions.push_back(a.dump());return int(o.actions.size()-1);};for(const auto&b:p["blocks"])o.blocks.push_back(WebBlock{str(b,"kind"),str(b,"text"),str(b,"area"),action(b["action"]),flag(b,"enabled"),flag(b,"selected"),flag(b,"primary"),str(b,"role"),str(b,"detail")});for(const auto*k:{"top","tabs"})for(const auto&b:p[k])(std::string(k)=="top"?o.top:o.tabs).push_back(WebControl{str(b,"text"),action(b["action"]),flag(b,"selected"),flag(b,"enabled")});return o;}
int main(int argc,char**argv){try{require(argc==4,"fixture/font/output required");std::ifstream fixtures(argv[1]),f(argv[2],std::ios::binary);std::vector<uint8_t>fontBytes((std::istreambuf_iterator<char>(f)),{}),a(Canvas::bytes),b(Canvas::bytes);Font font;require(font.init(fontBytes.data(),fontBytes.size()),"Font load failed");fs::create_directories(argv[3]);std::string line;int cases=0,frames=0,hits=0;while(std::getline(fixtures,line)){const auto q=J::parse(line);NativeStudy engine([](const std::string&,const std::string&){throw std::runtime_error("Pure rendering attempted a write");return false;});require(engine.enter(q["context"].dump()),"Native scene entry failed");auto actual=engine.page(),expected=decode(q["page"]);UI ua,ub;View va,vb;va.screen=vb.screen=Screen::WebLearning;va.web=actual;vb.web=expected;int count=1;for(int part=0;part<count;++part){va.web_page=vb.web_page=part;Canvas ca(a.data(),font),cb(b.data(),font);ua.render(ca,va);ub.render(cb,vb);require(a==b,"Native/legacy pixel mismatch");require(ua.answer_pages()==ub.answer_pages(),"Native pagination mismatch");count=ua.answer_pages();require(ua.buttons().size()==ub.buttons().size(),"Native hit map count mismatch");for(size_t i=0;i<ua.buttons().size();++i){const auto&x=ua.buttons()[i];const auto&y=ub.buttons()[i];require(x.rect.x==y.rect.x&&x.rect.y==y.rect.y&&x.rect.w==y.rect.w&&x.rect.h==y.rect.h&&x.label==y.label&&x.enabled==y.enabled,"Native hit geometry mismatch");const auto e=ua.hit(x.rect.x+x.rect.w/2,x.rect.y+x.rect.h/2);if(x.enabled)require(e.action==x.event.action&&e.value==x.event.value,"Native touch center mismatch");if(x.event.action==Action::WebAction)require(J::parse(actual.actions[x.event.value])==J::parse(expected.actions[y.event.value]),"Native hit action mismatch");++hits;}if(cases<60){std::ofstream image(fs::path(argv[3])/(std::to_string(cases)+"-"+std::to_string(part)+".pgm"),std::ios::binary);image<<"P5\n684 1216\n255\n";for(int y=0;y<1216;++y)for(int x=0;x<684;++x){const char pixel=char(ca.shade(x,y)*17);image.write(&pixel,1);}}++frames;}++cases;}std::cout<<"PASS native-only Canvas: "<<cases<<" scenes, "<<frames<<" identical frames, "<<hits<<" matching hit targets; no JS linked\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
